const REASON={tecUNFUNDED_PAYMENT:'sender did not have enough',tecNO_DST:'destination account does not exist',tecNO_LINE:'missing trust line',tecPATH_DRY:'no liquidity on the path',tecPATH_PARTIAL:'only part could be delivered',tecINSUF_RESERVE_LINE:'not enough reserve for a trust line',tecINSUF_RESERVE_OFFER:'not enough reserve for an offer',tecUNFUNDED_OFFER:'offer not funded',tecDST_TAG_NEEDED:'destination needs a tag',tecNO_PERMISSION:'not permitted',tecOWNERS:'account still owns objects',tecINSUFFICIENT_RESERVE:'not enough reserve',tecKILLED:'fill-or-kill offer did not fill',tecEXPIRED:'expired',tecNO_ENTRY:'object not found',tecFROZEN:'asset is frozen',tecDUPLICATE:'already exists'};
