async function acctAfter(q){let a=null;try{a=LumaAddr.toR?LumaAddr.toR(q):q}catch{}if(!a||!/^r[1-9A-HJ-NP-Za-km-z]{24,34}$/.test(a))return;const o=$('#res');if(!o||$('#xrb'))return;const b=document.createElement('div');b.id='xrb';b.innerHTML='<div class="t"><div class="sub">loading more details…</div></div>';o.appendChild(b);
 const safe=async c=>{try{return await ask(c)}catch{return null}};
 const [info,lines,offers,objs,nfts,tx]=await Promise.all([safe({command:'account_info',account:a,ledger_index:'validated'}),safe({command:'account_lines',account:a,limit:200}),safe({command:'account_offers',account:a,limit:50}),safe({command:'account_objects',account:a,limit:200}),safe({command:'account_nfts',account:a,limit:100}),safe({command:'account_tx',account:a,limit:100})]);
 const d=info&&info.account_data;if(!d){b.innerHTML='';return}
 const fl=d.Flags||0,flags=[[0x00100000,'Deposit authorization on'],[0x00020000,'Requires destination tag'],[0x00010000,'Disallows incoming LUMA'],[0x00800000,'Default ripple'],[0x00200000,'Global freeze'],[0x00400000,'Cannot freeze (NoFreeze)'],[0x00080000,'Disable master key']].filter(f=>fl&f[0]).map(f=>f[1]);
 const T=(tx&&tx.transactions)||[],cp={},rows=[];let first=null;
 T.forEach(x=>{const t=x.tx_json||x.tx||{};const c=t.Account===a?t.Destination:t.Account;if(c)cp[c]=(cp[c]||0)+1;const dt=t.date?(t.date+946684800)*1000:0;if(dt&&(first==null||dt<first))first=dt;rows.push([dt?new Date(dt).toISOString():'',t.TransactionType,t.Account===a?'out':'in',c||'',typeof t.Amount==='string'?+t.Amount/1e6:(t.Amount&&t.Amount.value)||'',(x.meta||x.metaData||{}).TransactionResult||'',t.hash||x.hash||''])});
 const failN=T.filter(x=>((x.meta||x.metaData||{}).TransactionResult||'tesSUCCESS')!=='tesSUCCESS').length;
 const bal=+d.Balance/1e6,res=(S.info&&S.info.validated_ledger)?+S.info.validated_ledger.reserve_base_xrp+(+S.info.validated_ledger.reserve_inc_xrp)*(d.OwnerCount||0):null;
 const risk=[];if(first&&Date.now()-first<86400000)risk.push('New account: first activity less than a day ago.');if(T.length>=20&&failN/T.length>.3)risk.push(`${Math.round(100*failN/T.length)}% of its recent transactions failed.`);if(fl&0x00200000)risk.push('This issuer has a global freeze on.');if(!(fl&0x00400000)&&(lines&&lines.lines||[]).some(l=>+l.balance<0))risk.push('Issues tokens and can still freeze them (NoFreeze is off).');
 const ln=(lines&&lines.lines)||[];
 b.innerHTML=`<div class="t"><div class="k">Account details</div>
  <div class="row" style="gap:.4rem;flex-wrap:wrap;margin:.4rem 0"><button class="pill" onclick="X.watchA('${a}')">${isW(a)?'★ Watching':'☆ Watch'}</button><button class="pill" onclick="X.labelA('${a}')">🏷 Label</button><button class="pill" onclick="copy('${dispL(a)}')">Copy L address</button><button class="pill" onclick="copy('${a}')">Copy r address</button><button class="pill" onclick="X.aexp2()">Export history CSV</button></div>
  ${P.labels[a]?`<div class="kv"><span>Your label</span><b>${esc(P.labels[a])}</b></div>`:''}
  <div class="kv"><span>Balance</span><b>${fmt(bal,6)} LUMA</b></div>${res!=null?`<div class="kv"><span>Reserved</span><b>${fmt(res,2)} LUMA · spendable ${fmt(Math.max(0,bal-res),2)}</b></div>`:''}
  <div class="kv"><span>Owned objects</span><b>${d.OwnerCount||0}</b></div><div class="kv"><span>Open offers</span><b>${offers&&offers.offers?offers.offers.length:'–'}</b></div><div class="kv"><span>NFTs held</span><b>${nfts&&nfts.account_nfts?nfts.account_nfts.length:'–'}</b></div>
  ${first?`<div class="kv"><span>First activity seen</span><b>${new Date(first).toLocaleString()} (${ago(Date.now()-first)} ago)</b></div>`:''}
  ${d.Domain?`<div class="kv"><span>Domain</span><b>${esc(hexStr(d.Domain))}</b></div>`:''}${d.RegularKey?`<div class="kv"><span>Regular key</span><b>${esc(short(d.RegularKey))}</b></div>`:''}${d.TransferRate?`<div class="kv"><span>Transfer fee</span><b>${((d.TransferRate/1e9-1)*100).toFixed(2)}%</b></div>`:''}
  ${flags.length?`<div class="fl">${flags.map(f=>`<span class="chip w">${esc(f)}</span>`).join('')}</div>`:''}
  ${risk.map(r=>`<div class="al warn">${esc(r)}</div>`).join('')}</div>
  ${ln.length?`<div class="t"><div class="k">Tokens held (${ln.length})</div><div class="list">${ln.slice(0,40).map(l=>`<div onclick="lookup('${l.account}')"><span class="chip v">${esc(tname(l.currency))}</span><span class="a">${esc(short(l.account))}</span><span class="m">${fmt(+l.balance,4)} · limit ${fmt(+l.limit,0)}</span></div>`).join('')}</div></div>`:''}
  ${Object.keys(cp).length?`<div class="t"><div class="k">Top counterparties (last ${T.length} transactions)</div><div class="list">${Object.entries(cp).sort((x,y)=>y[1]-x[1]).slice(0,8).map(([c,n])=>`<div onclick="lookup('${c}')"><span class="a">${esc(short(c))}${lab(c)}</span><span class="m">${n} tx</span></div>`).join('')}</div></div>`:''}`;
 X.hist=rows};
