X.exSearch=async()=>{const q={};for(const k of['type','memo','min','failed','cur'])if(EX.q[k]!==''){q[k==='cur'?'currency':k]=EX.q[k]}if(EX.q.acct)q.from=EX.q.acct;q.limit=50;const qs=Object.entries(q).map(([k,v])=>k+'='+encodeURIComponent(v)).join('&');EX.lastQ=qs;await exLoad('search','/search?'+qs)};
X.exSet=(k,v)=>{EX.q[k]=v};
X.exSave=()=>{if(!EX.lastQ)return toast('Run a search first');const L=JSON.parse(store.get('luma.scan.x.saved')||'[]');L.unshift({q:EX.lastQ,at:Date.now(),name:''});const nm=EX.lastQ.replace(/&limit=\d+/,'').slice(0,50);L[0].name=nm||'all';store.set('luma.scan.x.saved',JSON.stringify(L.slice(0,20)));toast('Saved to Watchlist')};
X.exRun=i=>{const L=JSON.parse(store.get('luma.scan.x.saved')||'[]');if(!L[i])return;EX.sec='search';EX.lastQ=L[i].q;exLoad('search','/search?'+L[i].q)};
X.exDel=i=>{const L=JSON.parse(store.get('luma.scan.x.saved')||'[]');L.splice(i,1);store.set('luma.scan.x.saved',JSON.stringify(L));paint()};
X.exAcct=async a=>{a=String(a||'').trim();if(!a)return;try{a=LumaAddr.toR?LumaAddr.toR(a):a}catch{}EX.acct=a;EX.sec='account';await exLoad('account','/account/'+encodeURIComponent(a));if(EX.d.account){try{EX.d.graph=await exGet('/graph/'+encodeURIComponent(a))}catch{EX.d.graph=null}paint()}};
X.exToken=async(c,i)=>{EX.tok=null;try{const[t,p]=await Promise.all([exGet('/token/'+encodeURIComponent(c)+'/'+i),exGet('/price/'+encodeURIComponent(c)+'/'+i).catch(()=>null)]);EX.tok={t,p}}catch(e){toast(e.message,1)}const s=sheet(`<h2 style="margin-top:0">${esc(c)}</h2>${EX.tok?exTokenHtml(EX.tok):''}`)};
function regBadge(r,short_){if(!r||!r.configured&&r.configured!==undefined)return'';if(r.status==='verified'){const lab=r.tier==='verified'?'Verified':'Reviewed',tip=r.tier==='verified'?'The issuer proved control of '+(r.domain||'its domain')+' (account Domain field and xrp-ledger.toml).':'Approved by the network operator without the domain proof.';return'<span class="pill" title="'+esc(tip)+'" style="background:'+(r.tier==='verified'?'rgba(0,196,111,.18);color:#00c46f':'rgba(120,160,255,.18);color:#8fb0ff')+'">'+lab+(short_?'':r.domain?' · '+esc(r.domain):'')+'</span>'+(r.stale&&!short_?' <span class="mut" style="font-size:.7rem">(registry out of date)</span>':'')}
 if(r.status==='suspended')return'<span class="pill" style="background:rgba(248,81,73,.2);color:#f85149" title="'+esc(r.reason||'')+'">Suspended'+(short_||!r.reason?'':': '+esc(r.reason))+'</span>';
 if(r.configured&&r.listed===false)return'<span class="pill mut" style="opacity:.7" title="This token is not in the operator\'s verified registry. That does not mean it is unsafe, but nobody has checked it.">Not verified</span>';return''}
function exTokenHtml({t,p}){const k=t.token||t,r=Array.isArray(k.risk)?{level:k.riskLevel,reasons:k.risk}:(k.risk||{});return`${k.registry&&k.registry.configured?'<div style="margin:.2rem 0 .6rem">'+regBadge(k.registry)+'</div>':''}${k.registry&&k.registry.status==='suspended'?'<div class="al warn" style="margin:.4rem 0"><b>The network operator has suspended this token.</b> '+esc(k.registry.reason||'It was reported as unsafe.')+' Do not buy or accept it.</div>':''}<div class="kv"><span>Issuer</span><span style="font-family:monospace;font-size:.74rem">${esc(short(k.issuer||k.iss||''))}</span></div><div class="kv"><span>Holders</span><b>${fmt(k.holders)}</b></div><div class="kv"><span>Supply</span><b>${num(k.supply)}</b></div><div class="kv"><span>Concentration (Gini)</span><b>${k.gini!=null?(+k.gini).toFixed(2):'–'}</b></div>${r.level?`<div class="al ${r.level==='high'?'warn':''}" style="margin:.5rem 0"><b>Risk: ${esc(r.level)}</b> ${esc((r.reasons||[]).join('; '))}</div>`:''}${p&&p.pool?`<div class="kv"><span>Pool price</span><b>${num(p.pricePerNative)} ${esc(p.quote)} per ${esc(p.base)}</b></div><div class="kv"><span>Liquidity</span><b>${num(p.liquidityNative)} ${esc(p.base)}</b></div>${p.thin?'<div class="sub">Thin pool: small trades move the price a lot.</div>':''}`:'<div class="sub">No AMM pool for this token.</div>'}${(k.topHolders||k.holdersTop||[]).slice(0,5).map(h=>`<div class="kv"><span style="font-family:monospace;font-size:.74rem">${esc(short(h.account||h.a))}</span><b>${num(h.amount||h.amt)}</b></div>`).join('')}`}
/* plain-language account summary built from indexer numbers */
function exAcctSummary(a){const p=a.account||a,tx=p.txs||p.txCount||p.n||0,first=p.first||p.firstSeen,tags=(p.tags||[]).join(', ');return`${tx?`This account has ${fmt(tx)} transactions on record`:'No transactions on record for this account'}${first?`, first seen ${new Date(first).toLocaleDateString()}`:''}.${p.balance!=null?` It holds ${num(p.balance)} ${esc(S.sym||'LUMA')}.`:''}${tags?` Labels: ${esc(tags)}.`:''}`}
X.exCsv=a=>{window.open(exBase()+'/export/account/'+encodeURIComponent(a)+'.csv'+(exKey()?'?key='+encodeURIComponent(exKey()):''),'_blank')};
X.exKey=v=>{store.set('luma.scan.apikey',String(v||'').trim());toast('Saved');EX.d={};paint()};
X.exVerify=async h=>{try{const r=await exGet('/verify/tx/'+h);toast(r.agree?`${r.agreeing||r.agree} node(s) agree`:'Nodes disagree: be careful',!r.agree)}catch(e){toast(e.message,1)}};
X.exPwa=()=>{try{navigator.serviceWorker.register('sw.js').then(()=>toast('Offline mode on: pages load without a connection'),e=>toast('Could not enable offline mode here',1))}catch{toast('Offline mode is not supported in this browser',1)}};
FN[13]=function(){
 exEnsure();const d=EX.d,sec=EX.sec;
 const tabs='<div class="row" style="gap:.3rem;flex-wrap:wrap;margin:.2rem 0 .8rem">'+exSecs.map(([k,l])=>exBtn(l,`X.exSec('${k}')`,sec===k?'on':'')).join('')+'</div>';
 let h=`<h2>Explore</h2><div class="sub">History and analytics from the LUMA indexer. Read-only.</div>${tabs}`;
 if(EX.err)h+=`<div class="t c12"><div class="al warn">${esc(EX.err)}</div><div class="sub">The indexer may not be running on this network yet.</div></div>`;
 if(EX.busy)h+='<div class="t c12 empty">loading…</div>';
 if(sec==='search'){const q=EX.q;h+=sec_('Search transactions',`<div class="row" style="gap:.4rem;flex-wrap:wrap"><select onchange="X.exSet('type',this.value)">${['','Payment','TrustSet','OfferCreate','AMMDeposit','NFTokenMint','AccountSet'].map(t=>`<option value="${t}" ${q.type===t?'selected':''}>${t||'any type'}</option>`).join('')}</select><input placeholder="memo contains" value="${esc(q.memo)}" oninput="X.exSet('memo',this.value)"><input placeholder="min amount" size="8" value="${esc(q.min)}" oninput="X.exSet('min',this.value)"><input placeholder="currency" size="6" value="${esc(q.cur)}" oninput="X.exSet('cur',this.value)"><input placeholder="from account" size="14" value="${esc(q.acct)}" oninput="X.exSet('acct',this.value)"><select onchange="X.exSet('failed',this.value)"><option value="">ok and failed</option><option value="0" ${q.failed==='0'?'selected':''}>only successful</option><option value="1" ${q.failed==='1'?'selected':''}>only failed</option></select>${exBtn('Search','X.exSearch()','on')}${exBtn('Save','X.exSave()')}</div>`);
  const r=d.search;if(r)h+=sec_(`${fmt(r.count)} results`,`<div class="list">${(r.transactions||[]).map(exTxRow).join('')||'<div class="sub">Nothing matches.</div>'}</div>`)}
 if(sec==='tokens'&&d.tokens)h+=sec_('Tokens',`<div class="list">${(d.tokens.tokens||[]).map(t=>`<div class="row" style="gap:.5rem;cursor:pointer" onclick="X.exToken('${esc(t.cur)}','${esc(t.iss)}')"><b>${esc(t.cur)}</b>${regBadge({configured:!!t.status,status:t.status==='unlisted'?undefined:t.status,listed:t.status!=='unlisted',tier:t.tier},1)}<span style="flex:1;font-family:monospace;font-size:.72rem">${esc(short(t.iss))}</span><span class="mut">${fmt(t.holders)} holders</span></div>`).join('')||'<div class="sub">No tokens indexed yet.</div>'}</div>`);
 if(sec==='pools'&&d.pools)h+=sec_('AMM pools (7 days)',`<div class="list">${(d.pools.pools||[]).map(p=>`<div class="row" style="gap:.5rem"><span style="flex:1;font-family:monospace;font-size:.74rem">${esc(short(p.acct))}</span><span class="mut">${fmt(p.n||p.events)} events</span><b>${num(p.delta||p.net||0)}</b></div>`).join('')||'<div class="sub">No pool activity.</div>'}</div><div class="sub">Net change in the pool. Positive = liquidity added.</div>`);
 if(sec==='whales'&&d.whales)h+=sec_('Large transfers (10,000+)',`<div class="list">${(d.whales.transactions||[]).map(exTxRow).join('')||'<div class="sub">None yet.</div>'}</div>`);
 if(sec==='anomalies'&&d.anomalies)h+=sec_('Unusual activity',`<div class="list">${(d.anomalies.anomalies||d.anomalies.items||[]).map(a=>`<div><span class="chip w">${esc(a.kind||a.type||'notice')}</span> ${esc(a.msg||a.message||a.text||JSON.stringify(a))}</div>`).join('')||'<div class="sub">Nothing unusual.</div>'}</div>`);
 if(sec==='health'&&d.health){const x=d.health;h+=sec_('Network health',`<div class="big">${x.score!=null?fmt(x.score):'–'}<small> / 100</small></div><div class="list">${(x.factors||x.checks||[]).map(f=>`<div>${f.ok===false?'⚠':'✓'} ${esc(f.name||f.label||'')} <span class="mut">${esc(f.note||f.detail||'')}</span></div>`).join('')}</div>`)}
 if(sec==='account'){h+=sec_('Look up an account',`<div class="row" style="gap:.4rem"><input id="exa" placeholder="address" style="flex:1" value="${esc(EX.acct||'')}">${exBtn('Go',"X.exAcct(document.getElementById('exa').value)",'on')}</div>`);
  if(d.account){const a=d.account.account||d.account;h+=sec_('Summary',`<div>${exAcctSummary(d.account)}</div><div class="row" style="gap:.4rem;margin-top:.5rem">${exBtn('Open in Accounts',`lookup('${esc(EX.acct)}')`)}${exBtn('Download CSV',`X.exCsv('${esc(EX.acct)}')`)}</div>`);
   const g=d.graph;if(g&&(g.edges||[]).length)h+=sec_('Who they transact with',`<div class="list">${g.edges.slice(0,10).map(e=>`<div class="row" style="gap:.5rem;cursor:pointer" onclick="X.exAcct('${esc(e.src===EX.acct?e.dst:e.src)}')"><span style="flex:1;font-family:monospace;font-size:.74rem">${esc(short(e.src===EX.acct?e.dst:e.src))}</span><span class="mut">${e.src===EX.acct?'sent':'received'} ${fmt(e.n)}×</span><b>${num(e.tot)} ${esc(e.cur||'')}</b></div>`).join('')}</div>`)}}
 if(sec==='watch'){const L=JSON.parse(store.get('luma.scan.x.saved')||'[]'),W=P.watch||[];h+=sec_('Saved searches',`<div class="list">${L.map((s,i)=>`<div class="row" style="gap:.5rem"><span style="flex:1;cursor:pointer" onclick="X.exRun(${i})">${esc(s.name)}</span>${exBtn('Delete',`X.exDel(${i})`)}</div>`).join('')||'<div class="sub">Run a search and press Save.</div>'}</div>`);h+=sec_('Watched accounts',`<div class="list">${W.map(a=>`<div class="row" style="gap:.5rem;cursor:pointer" onclick="X.exAcct('${esc(a)}')"><span style="font-family:monospace;font-size:.74rem">${esc(short(a))}</span></div>`).join('')||'<div class="sub">Open an account and use Watch on the Accounts page.</div>'}</div>`)}
 if(sec==='compare'&&d.compare){const row=(n)=>{const o=d.compare[n];if(!o||o.err)return`<div class="t"><div class="k">${n==='main'?'Mainnet':'Testnet'}</div><div class="sub">${esc((o&&o.err)||'no data')}</div></div>`;const s=o.s.indexed||{},nd=o.s.node||{};return`<div class="t"><div class="k">${n==='main'?'Mainnet':'Testnet'}</div><div class="kv"><span>Latest indexed ledger</span><b>${fmt(s.last)}</b></div><div class="kv"><span>Transactions</span><b>${fmt(s.transactions)}</b></div><div class="kv"><span>Indexer lag</span><b>${nd.lag==null?'–':fmt(nd.lag)}</b></div><div class="kv"><span>Health</span><b>${o.h&&o.h.score!=null?fmt(o.h.score)+'/100':'–'}</b></div></div>`};h+=`<div class="grid">${row('main')}${row('test')}</div>`}
 if(sec==='more'){h+=sec_('Tools',`<div class="row" style="gap:.4rem;flex-wrap:wrap">${exBtn('Enable offline mode','X.exPwa()')}${exBtn('API docs',`window.open(exBase()+'/explorer','_blank')`)}</div><div class="sub" style="margin-top:.5rem">Offline mode keeps this page available without internet; live data needs a connection.</div>`);h+=sec_('API key (optional)',`<div class="row" style="gap:.4rem"><input id="exk" placeholder="lk_..." style="flex:1" value="${esc(exKey())}">${exBtn('Save',"X.exKey(document.getElementById('exk').value)")}</div><div class="sub">A key raises your request limit. Ask the network operator for one.</div>`)}
 return h};
